"""Design only: evaluate residual authority and matched disturbances; no RL training."""
import _bootstrap,json
import numpy as np,pandas as pd
from src.model import ROOT,write_json
from src.workspace.feedforward_study import RUN

def main():
    d=pd.read_csv(ROOT/'results/phase2c3b_controller_comparison.csv');strong=json.loads((RUN/'methods_frozen.json').read_text(encoding='utf-8'))['strong_method'];rules=json.loads((RUN/'rl_design_assessment_rules.json').read_text(encoding='utf-8'));p=pd.read_csv(ROOT/'results/phase2c3b_control_phase_errors.csv');a=pd.read_csv(ROOT/'results/phase2c3b_action_authority.csv');paired=pd.read_csv(ROOT/'results/phase2c3b_paired_effects.csv');baseline=d[(d.stage=='load')&(d.method==strong)].iloc[0];basephases=p[(p.stage=='load')&(p.method==strong)];evidence=[]
    for pattern in ['positive','negative','sine20','sine50']:
        q=p[(p.stage=='authority')&p.trial.str.endswith('_'+pattern)]
        for phase in ['rise_accel','rise_decel','top_hold','fall_accel','fall_decel']:
            b=basephases[basephases.phase==phase];z=q[q.phase==phase]
            if len(b) and len(z):evidence.append(dict(pattern=pattern,phase=phase,zero_probe_z_rmse_mm=float(b.z_rmse_mm.iloc[0]),probe_z_rmse_mm=float(z.z_rmse_mm.iloc[0]),ratio=float(z.z_rmse_mm.iloc[0]/b.z_rmse_mm.iloc[0])))
    safe=d[d.stage!='joint_preflight'];all_safe=bool(safe.success.all() and (safe.additional_force_peak_N<=5+1e-8).all() and (safe.additional_force_rate_peak_N_s<=20+1e-6).all() and (safe.native_saturation_steps==0).all());effective=bool((a.effective_peak_leg_N>rules['minimum_effective_probe_leg_N']).all());has_improving_window=any(x['ratio']<.99 for x in evidence);headroom=float(safe[safe.method==strong].remaining_shared_force_N.min());residual=float(baseline.z_rmse_mm);paired_row=paired[paired.method==strong].iloc[0];measurable=bool(max(paired_row.paired_load_position_difference_peak_mm,paired_row.paired_lag_position_difference_peak_mm)>=rules['minimum_residual_or_perturbation_scale_mm']);go=bool(all_safe and effective and has_improving_window and measurable and headroom>=rules['minimum_remaining_shared_headroom_N'] and residual>=rules['minimum_residual_or_perturbation_scale_mm'])
    # Physical/action filters do not by themselves certify a useful research task.
    # The task explicitly requires considering non-Z errors before expanding RL.
    formal=d[d.stage=='formal'];tradeoffs=[]
    for T in [4,6,8,10]:
        f=formal[(formal.method==strong)&(formal.rise_s==T)].iloc[0];c=formal[(formal.method=='C4')&(formal.rise_s==T)].iloc[0]
        xy_share=1-(f.z_rmse_mm/f.position_rmse_mm)**2
        tradeoffs.append(dict(rise_s=T,C4_xy_peak_mm=float(c.xy_peak_mm),FF_xy_peak_mm=float(f.xy_peak_mm),xy_peak_ratio=float(f.xy_peak_mm/c.xy_peak_mm),non_Z_fraction_of_position_squared_error=float(xy_share),C4_position_rmse_mm=float(c.position_rmse_mm),FF_position_rmse_mm=float(f.position_rmse_mm)))
    unresolved_non_Z=any(x['FF_xy_peak_mm']>x['C4_xy_peak_mm'] and x['non_Z_fraction_of_position_squared_error']>.5 for x in tradeoffs)
    decision='GO TO LARGE-MOTION RL PILOT' if go and not unresolved_non_Z else 'LARGE-MOTION RL PILOT CONDITIONALLY BLOCKED'
    previous=ROOT/'results/phase2c3b_rl_task_recommendation.json';snapshot=RUN/'rl_physical_filter_initial_assessment.json'
    if previous.exists() and not snapshot.exists():snapshot.write_text(previous.read_text(encoding='utf-8'),encoding='utf-8')
    result=dict(decision=decision,scope='Only bounded MuJoCo pure-Z residual research; not a hardware safety or PPO superiority claim',base_controller=strong,main_candidate=dict(amplitude_m=.05,rise_s=6.,tau_s=.005,external_Fz_N=-5.5,external_on_s=5.2,external_off_s=11.),checks=dict(all_completed_and_budget_safe=all_safe,nonzero_effective_action=effective,phase_specific_improvement_possible=has_improving_window,remaining_shared_headroom_N=headroom,baseline_loaded_z_rmse_mm=residual),fixed_probe_results=a.to_dict('records'),phase_authority_evidence=evidence,initial_actor_action=dict(dimensions=1,units='normalised [-1,1] mapped to delta_Fz_N',suggested_start_scale_N=.1,largest_direct_probe_scale_N=.25,start_scale_is_candidate_not_all_state_safety_guarantee=True,total_shared_budget_per_leg_N=5,total_shared_rate_N_s=20),future_frequencies_hz=[20,50],same_physical_exposure_required=True,nominal_gamma_at_50ms=.99,gamma_rule='gamma(dt)=0.99**(dt/0.05); match GAE time scale and rollout physical duration',no_training_executed=True,mechanical_hard_stops_unknown=30,connected_socket_collision_incomplete=True,additional_joint_conditions_not_executed=['tau10ms+external load','mass/gain randomisation','negative Z'],next_gate='New environment zero-action exact FF baseline, observer on/off invariance, new scales/reward checks,1024-decision smoke only; further2-seed budget must be frozen separately')
    result.update(physical_action_filters_pass=go,measurable_matched_perturbation=measurable,non_Z_tradeoffs=tradeoffs,unresolved_non_Z_dominance=unresolved_non_Z,decision_explanation='Predefined bounded physical/action filters passed but non-target XY increases and dominates residual3D error. This is research-readiness judgement required by task, not posthoc coefficient tuning or a safety-threshold relaxation. Diagnose full-task coupling before PPO.',next_gate='First diagnose FF-induced XY/attitude tradeoff, check whether nominal full-task feedforward can address it without changing limits; then separately approve a pure-Z learning objective or verify other action channels. Future RL also needs zero-action exact equivalence, observation/reward audit and only1024-decision smoke.')
    write_json(ROOT/'results/phase2c3b_rl_task_recommendation.json',result);pd.DataFrame(evidence).to_csv(ROOT/'results/phase2c3b_phase_action_effects.csv',index=False);pd.DataFrame(tradeoffs).to_csv(ROOT/'results/phase2c3b_non_target_tradeoff.csv',index=False);print(decision,result['checks'],'non_Z_dominance',unresolved_non_Z)
if __name__=='__main__':main()
